// Expected POST body:
// {
//   site_id: 41,
//   category: 'agency' | 'ecommerce' | 'tech' | 'local_business' | 'restaurant' | 'nonprofit',
//   name: 'JHD Advisor',
//   domain: 'https://www.jhdadvisor.com',
//   phone: '+1 (917) 338-7086',
//   email: 'info@jhdadvisor.com',
//   location: 'Long Island, NY',
//   tagline: 'Custom hero headline (optional)',
//   color1: '#7c3aed (optional)',
//   color2: '#06b6d4 (optional)'
// }

const body = $input.first().json.body || $input.first().json;

const VALID_CATEGORIES = ['agency','ecommerce','tech','local_business','restaurant','nonprofit'];

if (!body.site_id) throw new Error('site_id is required');
if (!body.category || !VALID_CATEGORIES.includes(body.category)) {
  throw new Error(`category must be one of: ${VALID_CATEGORIES.join(', ')}`);
}
if (!body.name) throw new Error('name is required');

const config = {
  site_id:  parseInt(body.site_id),
  category: body.category,
  name:     body.name,
  domain:   body.domain || '',
  phone:    body.phone  || '',
  email:    body.email  || '',
  location: body.location || '',
  tagline:  body.tagline  || '',
  color1:   body.color1   || '',
  color2:   body.color2   || '',
  started_at: new Date().toISOString(),
};

console.log('Build config:', JSON.stringify(config, null, 2));
return [{ json: config }];

