const config = $('Validate & Normalize Input').first().json;
const aiRaw = $('AI: Generate Custom Content').first().json.text || $('AI: Generate Custom Content').first().json.content || '';

let aiContent = {};
try {
  // Strip markdown code blocks if present
  const clean = aiRaw.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  aiContent = JSON.parse(clean);
} catch(e) {
  console.warn('AI JSON parse failed, using defaults:', e.message);
}

const merged = {
  ...config,
  ai_hero_headline: aiContent.hero_headline || '',
  ai_hero_sub:      aiContent.hero_sub      || '',
  ai_services:      JSON.stringify(aiContent.services || []),
  ai_blog_topics:   JSON.stringify(aiContent.blog_topics || []),
  ai_cta_headline:  aiContent.cta_headline  || '',
  ai_cta_sub:       aiContent.cta_sub       || '',
  ai_footer_tagline:aiContent.footer_tagline|| '',
};

console.log('Merged config ready. Services count:', (aiContent.services||[]).length);
return [{ json: merged }];

