];

// Parse AI blog topics
let blogTopics = [];
try { blogTopics = JSON.parse(cfg.ai_blog_topics); } catch(e) {}
if (!blogTopics.length) blogTopics = [
  ['Key Topic 1 for Your Business in 2026', 'Why this matters for your customers.'],
  ['Key Topic 2: A Guide for Business Owners', 'Practical steps you can take today.'],
  ['How to Get the Most From Our Services', 'Tips and insights from our team.'],
];

const heroHeadline = cfg.ai_hero_headline || cfg.tagline || `${cfg.name} — here to serve you.`;
const heroSub      = cfg.ai_hero_sub      || `${cfg.name} provides exceptional service for clients in ${cfg.location || 'your area'}.`;
const ctaHeadline  = cfg.ai_cta_headline  || `Ready to work with ${cfg.name}?`;
const ctaSub       = cfg.ai_cta_sub       || `Contact us today to get started.`;
const footerTag    = cfg.ai_footer_tagline || `Quality · Reliability · Results`;

// Build service cards HTML
const svcCards = services.map(s =>
  `<div class="wb-card"><div class="wb-icon">${s.icon||'SVC'}</div><h3>${s.name}</h3><p>${s.desc}</p></div>`
).join('\n');

// Build blog cards HTML
const blogCards = blogTopics.slice(0,3).map(([title, sub]) =>
  `<a href="/blog" class="wb-blog-card"><span class="wb-blog-tag">Insights</span><h3>${title}</h3><p>${(sub||'').substring(0,120)}...</p></a>`
