const cfg       = $('Build Homepage HTML').first().json;
const blogId    = $('Odoo: Create Blog').first().json.result;
const blogTopics = cfg.blog_topics_parsed || [];

const ODOO = 'https://country-cove-inc.odoo.com';
const DB='country-cove-inc', UID=2, PASS='M@nhattan1234';
const AUTHORS = ['James Whitfield','Sarah Monroe','Daniel Hargrove','Emily Thornton','Michael Ashworth'];

const SAFE_COVER = JSON.stringify({
  'background-image':'none',
  'background_color_class':'o_cc3',
  'opacity':'0.2',
  'resize_class':''
});

let rpcId = 100;
async function rpc(model, method, args, kw={}) {
  const r = await fetch(`${ODOO}/jsonrpc`, {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({
      jsonrpc:'2.0', method:'call', id: ++rpcId,
      params: { service:'object', method:'execute_kw',
        args:[DB, UID, PASS, model, method, args, kw] }
    })
  });
  const d = await r.json();
  if (d.error) throw new Error(d.error.data?.message || 'RPC error');
  return d.result;
}

const results = [];
for (let i = 0; i < blogTopics.length; i++) {
  const [title, subtitle] = blogTopics[i];
  const author = AUTHORS[i % AUTHORS.length];

  // Get or create partner
  let partnerRows = await rpc('res.partner','search_read',
    [[['name','=',author],['is_company','=',false]]],{fields:['id'],limit:1});
  let partnerId = partnerRows[0]?.id || await rpc('res.partner','create',[{name:author,is_company:false}]);

