  <li><strong>Measure and adjust</strong> — track results and refine your approach weekly</li>
  <li><strong>Scale what works</strong> — double down on proven strategies</li>
</ol>
<h2 style="font-size:26px;margin:32px 0 12px;font-weight:900;">Frequently Asked Questions</h2>
<h3 style="font-size:18px;margin:20px 0 6px;font-weight:800;">How quickly will I see results?</h3>
<p>Most clients see measurable improvement within 30 days of consistent implementation.</p>
<h3 style="font-size:18px;margin:20px 0 6px;font-weight:800;">Do I need special expertise?</h3>
<p>No. We guide you through every step. Our team handles the complexity so you can focus on your business.</p>
<div style="background:linear-gradient(135deg,${cfg.color1||'#7c3aed'},${cfg.color2||'#06b6d4'});border-radius:16px;padding:36px;margin:40px 0;color:#fff;text-align:center;">
  <h3 style="margin:0 0 10px;font-size:22px;font-weight:900;">Ready to get started?</h3>
  <p style="margin:0 0 22px;opacity:.9;">${cfg.name} is here to help. Contact us today.</p>
  <a href="/contact" style="display:inline-block;background:#fff;color:${cfg.color1||'#7c3aed'};font-weight:900;font-size:15px;padding:14px 28px;border-radius:10px;text-decoration:none;">Contact Us</a>
</div>
</article>`;

  const postId = await rpc('blog.post','create',[{
    blog_id: blogId,
    website_id: cfg.site_id,
    name: title,
    subtitle: subtitle,
    content: content,
    author_id: partnerId,
    website_meta_title: title.substring(0,60),
    website_meta_description: subtitle.substring(0,155),
    website_published: true,
    is_published: true,
    cover_properties: SAFE_COVER,
  }]);

  results.push({ title, author, post_id: postId });
}

return [{ json: { ...cfg, blog_id: blogId, posts_created: results } }];
